        returns (StreamScopedCoreFinalityFacts memory);

function tokenCollectionIdentity(uint256 tokenId)
        external
        view
        returns (bool mappingExists, uint256 collectionId, uint256 collectionSerial, bool burned);

function fulfillEntropy(bytes32 requestKey, bytes32 rawRandomness)
        external
        returns (uint8 outcome);

function registerEntropyScope(uint256 collectionId, uint8 scopeKind, bytes32 scopeRef)
        external
        returns (bytes32 scopeId);

function requestEntropy(uint256 tokenId)
        external
        payable
        returns (bytes32 requestKey, uint256 providerRequestId);

function onTokenMinted(
        uint256 collectionId,
        uint256 tokenId,
        address recipient,
        bytes32 mintCommitment
    ) external;

function requestScopeEntropy(bytes32 scopeId, bytes32 scopeInputsHash)
        external
        payable
        returns (bytes32 requestKey, uint256 providerRequestId);

function terminalFreezeVetoGuardian(bytes32 scopeHash)
        external
        view
        returns (address guardian, uint64 vetoDeadline);

records.summary:
@notice Terminal-freeze veto guardian for a staged-freeze scope key
         ([GOV-WINDOWS] veto surface shape).
 @dev The registry requires a nonzero guardian to schedule any terminal freeze and
      re-resolves the guardian at veto time; it enforces its own veto window
      (`notBefore`, floored at 72 hours), so `vetoDeadline` is informational here.

